    "you-are-about-to-create-a-student-account-on-pil": {
        "de": "Du bist dabei, ein „Schülerin/Schüler“-Konto auf PILA (der Plattform für innovative Lernbewertungen) zu erstellen. Das bedeutet, dass Du damit einverstanden bist, dass Know Learning, die PILA-Entwicklerinnen und -Entwickler, Daten über Deine Aktivitäten sammeln und speichern können. Du stimmst außerdem zu, dass einige der Aktivitätsdaten von Google Analytics, Google Cloud Platform und OpenAI verarbeitet (aber niemals gespeichert) werden dürfen, damit die Plattform funktioniert. OpenAI wird beispielsweise NIEMALS Deine Antworten auf Fragebögen erhalten.",
        "en": "You are about to create a “student” account on PILA (the Platform for Innovative Learning Assessments). ​  This means you agree that Know Learning, the PILA developers, can collect and store data about your activity.​ You also agree that some of the activity data may be processed (but never stored) by Google Cloud Platform and OpenAI, to make the platform work. For example, OpenAI will NEVER receive your responses to questionnaires.",
        "es": "Está a punto de crear una cuenta de \"estudiante\" en PILA (la Plataforma para evaluaciones de aprendizaje innovadoras). ​ Esto significa que acepta que Know Learning, los desarrolladores de PILA, pueden recopilar y almacenar datos sobre su actividad. También acepta que algunos de los datos de la actividad pueden ser procesados ​​(pero nunca almacenados) por Google Analytics, Google Cloud Platform y OpenAI, para que la plataforma funcione. Por ejemplo, OpenAI NUNCA recibirá sus respuestas a los cuestionarios.",
        "fr": "Tu es sur le point de créer un compte “élève” sur PILA (la Plateforme pour les Évaluations Innovantes de l’Apprentissage). Cela signifie que tu acceptes que Know Learning, les développeurs de PILA, puissent collecter et stocker des données sur ton activité. Tu acceptes également que certaines de ces données puissent être traitées (mais jamais stockées) par Google Analytics, Google Cloud Platform et OpenAI afin de faire fonctionner la plateforme. Par exemple, OpenAI ne recevra JAMAIS tes réponses aux questionnaires.",
        "km": "ដោយបង្កើតគណនី និងប្រើវេទិកាសម្រាប់ការវាយតម្លៃការសិក្សានិងច្នៃប្រឌិត (PILA) អ្នកយល់ព្រមថា KnowLearning អាចប្រមូល និងរក្សាទិន្នន័យអំពីសកម្មភាពរបស់អ្នក ហើយ Google Analytics និង Google Cloud Platform អាចដំណើរការទិន្នន័យនេះ។",
        "lv": "Tu gatavojaties izveidot “skolēna” kontu PILA (Innovative Learning Assessments) platformā. ​Tas nozīmē, ka piekrīti, ka Know Learning, PILA izstrādātāji, var vākt un uzglabāt datus par tavām darbībām.​ Tu arī piekrīti, ka Google Analytics, Google Cloud Platform un OpenAI var apstrādāt (bet nekad nesaglabāt) dažus aktivitāšu datus, lai platforma darbotos. Piemēram, OpenAI NEKAD nesaņems tavas anketu atbildes.",
        "nl": "Je staat op het punt een “studenten”-account aan te maken op PILA (het Platform voor Innovatieve Leertoetsen). Dit betekent dat u ermee akkoord gaat dat Know Learning, de PILA-ontwikkelaars, gegevens over uw activiteit kan verzamelen en opslaan. U gaat er ook mee akkoord dat sommige activiteitsgegevens kunnen worden verwerkt (maar nooit opgeslagen) door Google Analytics, Google Cloud Platform en OpenAI, om het platform te laten werken. OpenAI zal bijvoorbeeld NOOIT uw antwoorden op vragenlijsten ontvangen.",
        "pl": "Masz zamiar utworzyć konto „ucznia” na PILA (Platforma Innowacyjnych Oceniania Nauki). Oznacza to, że zgadzasz się, aby Know Learning, twórcy PILA, mogli gromadzić i przechowywać dane o Twojej aktywności. Zgadzasz się również, że niektóre dane dotyczące aktywności mogą być przetwarzane (ale nigdy przechowywane) przez Google Analytics, Google Cloud Platform i OpenAI, aby platforma działała poprawnie. Na przykład OpenAI NIGDY nie otrzyma Twoich odpowiedzi na ankiety.",
        "pt": "Você está prestes a criar uma conta de “estudante” no PILA (a Plataforma para Avaliações de Aprendizagem Inovadoras). ​ Isso significa que você concorda que a Know Learning, os desenvolvedores do PILA, podem coletar e armazenar dados sobre sua atividade.​ Você também concorda que alguns dos dados da atividade podem ser processados ​​(mas nunca armazenados) pelo Google Analytics, Google Cloud Platform e OpenAI, para fazer a plataforma funcionar. Por exemplo, a OpenAI NUNCA receberá suas respostas aos questionários.",
        "sk": "Chystáš sa vytvoriť „žiacky“ účet na PILA (Platforma pre hodnotenie inovatívneho vzdelávania). ​ To znamená, že súhlasíš s tým, aby spoločnosť Know Learning, ktorá je vývojárom platformy PILA, mohla zhromažďovať a ukladať údaje o tvojej aktivite.​ Tiež súhlasíš s tým, že niektoré z údajov o aktivitách môžu byť spracované (ale nikdy nie uložené) pomocou Google Analytics, Google Cloud Platform a OpenAI, aby platforma fungovala. Napríklad OpenAI NIKDY nedostane tvoje odpovede na dotazníky.",
        "th": "คุณกำลังจะสร้างบัญชี “นักเรียน” บน PILA (แพลตฟอร์มการประเมินการเรียนรู้เชิงนวัตกรรม) ซึ่งหมายความว่าคุณยอมรับว่า Know Learning ผู้พัฒนา PILA สามารถเก็บและจัดเก็บข้อมูลเกี่ยวกับกิจกรรมของคุณได้ นอกจากนี้คุณยังยอมรับว่าข้อมูลบางส่วนของกิจกรรมอาจถูกประมวลผล (แต่จะไม่ถูกจัดเก็บ) โดย Google Analytics, Google Cloud Platform และ OpenAI เพื่อให้แพลตฟอร์มทำงานได้ อย่างเช่น OpenAI จะไม่เคยรับคำตอบของคุณจากแบบสอบถาม"
    },
