        "km": "អ្នកអាចស្នើសុំចូលរួមវិញនៅពេលក្រោយដោយទាក់ទងជាមួយជំនួយ ឬលុបស្លាកបោះបង់ចេញ",
        "lv": "Varat pieprasīt atteikšanos vēlāk, sazinoties ar atbalsta dienestu vai noņemot atteikšanās atzīmi",
        "nl": "U kunt later een verzoek indienen om u weer aan te melden door contact op te nemen met de ondersteuning of door de opt-out-tag te verwijderen",
        "pl": "Możesz poprosić o ponowne dołączenie później, kontaktując się z pomocą techniczną lub usuwając znacznik rezygnacji",
