        "nl": "Heeft u geen toegangscode? Neem contact op met edu.pila@oecd.org om interesse te tonen in het gebruik van PILA in uw klaslokaal of voor uw onderzoek.",
        "pl": "Nie masz kodu dostępu? Skontaktuj się z edu.pila@oecd.org, aby wyrazić zainteresowanie używaniem PILA w swojej klasie lub w badaniach.",
