        "pt": "Uma cópia desta tarefa será criada com todas as configurações preservadas. A duplicata será salva como rascunho.",
        "sk": "Vytvorí sa kópia tejto úlohy so zachovaním všetkých nastavení. Duplikát sa uloží ako koncept.",
        "th": "ระบบจะสร้างสำเนาของงานนี้โดยคงการตั้งค่าทั้งหมดไว้ สำเนาจะถูกบันทึกเป็นฉบับร่าง"
