    "steps-to-reproduce-the-bug-are-required-e-g-1-na": {
        "de": "Es sind Schritte zur Reproduktion des Fehlers erforderlich (z. B. 1. zu [URL] navigieren, 2. eine gültige E-Mail-Adresse und ein gültiges Passwort eingeben, 3. auf die Anmeldeschaltfläche klicken, 4. darauf achten, dass nichts passiert)",
        "en": "Steps to reproduce the bug are required (e.g. 1. navigate to [URL], 2. enter a valid email and password, 3. click the login button, 4. observe that nothing happens) ",
        "es": "Se requieren pasos para reproducir el error (por ejemplo, 1. navegar a [URL], 2. ingresar un correo electrónico y una contraseña válidos, 3. hacer clic en el botón de inicio de sesión, 4. observar que no sucede nada)",
        "fr": "Les étapes pour reproduire le dysfonctionnement sont requises (ex. 1. Accédez à [URL], 2. Saisissez une adresse e-mail et un mot de passe valides, 3. Cliquez sur le bouton de connexion, 4. Observez qu’il ne se passe rien)",
        "km": "ត្រូវការជំហានដើម្បីធ្វើឡើងម្ដងទៀត (ឧ.1. ចូលទៅកាន់ [URL], 2. បញ្ចូលអ៊ីមែល និងពាក្យសម្ងាត់ត្រឹមត្រូវ, 3. ចុចប៊ូតុង \"ចូល\", 4.សង្កេតឃើញថាមិនមានអ្វីកើតឡើងទេ)",
        "lv": "Ir jāveic darbības, lai atkārtotu kļūdu (piemēram, 1. dodieties uz [URL], 2. ievadiet derīgu e-pastu un paroli, 3. noklikšķiniet uz pieteikšanās pogas, 4. novērojiet, ka nekas nenotiek)",
        "nl": "Er zijn stappen nodig om de bug te reproduceren (bijvoorbeeld 1. navigeer naar [URL], 2. voer een geldig e-mailadres en wachtwoord in, 3. klik op de login-knop, 4. kijk of er niets gebeurt)",
        "pl": "Kroki do odtworzenia są wymagane (np. 1.Przejdź do [URL], 2.Wprowadź poprawny adres e-mail i hasło, 3.Kliknij przycisk logowania, 4.Zauważ, że nic się nie dzieje)",
        "pt": "São necessárias etapas para reproduzir o bug (por exemplo, 1. navegar até [URL], 2. inserir um e-mail e senha válidos, 3. clicar no botão de login, 4. observar se nada acontece)",
        "sk": "Vyžadujú sa popis reprodukcie chyby (napr. 1. prejdite na [URL], 2. zadajte platný e-mail a heslo, 3. kliknite na tlačidlo prihlásenia, 4. sledujte, či sa nič nedeje)",
        "th": "จำเป็นต้องระบุขั้นตอนในการทำซ้ำ (เช่น 1. ไปที่ [URL], 2.ป้อนอีเมลและรหัสผ่านที่ถูกต้อง, 3.คลิกปุ่มเข้าสู่ระบบ, 4.สังเกตว่าไม่มีอะไรเกิดขึ้น)"
    },
