    "👉-quick-troubleshooting-checklist-please-make-s": {
        "de": "## 👉 Schnelle Checkliste zur Fehlerbehebung \n\nBitte stellen Sie sicher, dass Sie die folgenden Schritte ausprobiert haben, bevor Sie einen Bericht einreichen: \n\n- Verwenden Sie einen empfohlenen Browser (Chrome) \n- Aktualisieren Sie die Seite \n- Schließen Sie Ihren Browser und öffnen Sie ihn erneut \n- Löschen Sie Ihren Browserverlauf/Cache \n- Überprüfen Sie, ob Ihre Internetverbindung schnell ist",
        "en": "##  👉 Quick Troubleshooting Checklist\n\nPlease make sure you've tried these steps before submitting a report:\n\n- Use a recommended browser (Chrome)\n- Refresh the page\n- Close and reopen your browser\n- Clear your broswer history/cache\n- Check that your internet connection is speedy",
        "es": "## 👉 Lista de verificación rápida para solucionar problemas \n\nAsegúrese de haber probado estos pasos antes de enviar un informe: \n\n- Utilice un navegador recomendado (Chrome) \n- Actualizar la página \n- Cierra y vuelve a abrir tu navegador \n- Borra el historial/caché de tu navegador \n- Comprueba que tu conexión a Internet sea rápida.",
        "fr": "## 👉 Guide de dépannage\n\nVeuillez vous assurer d’avoir essayé ces étapes avant de soumettre un rapport :\n\n- Utilisez un navigateur recommandé (Chrome)  \n- Actualisez la page  \n- Fermez et rouvrez votre navigateur  \n- Effacez l’historique/le cache de votre navigateur  \n- Vérifiez que votre connexion Internet est rapide",
        "km": "## 👉 បញ្ជីត្រួតពិនិត្យដើម្បីដោះស្រាយបញ្ហាបន្ទាន់\n\nសូមធានាថាអ្នកបានសាកល្បងជំហានទាំងនេះមុនពេលផ្ញើរបាយការណ៍៖\n\n- ប្រើកម្មវិធីរុករកដែលបានផ្តល់អនុសាសន៍ (Chrome)  \n- ធ្វើឱ្យទំព័របានទាន់សម័យ  \n- បិទ និងបើកកម្មវិធីរុករករបស់អ្នកម្តងទៀត  \n- សម្អាតប្រវត្តិ/ឃ្លាំងសម្ងាត់របស់កម្មវិធីរុករក  \n- ពិនិត្យមើលថាការតភ្ជាប់អ៊ីនធឺណិតរបស់អ្នកលឿន",
        "lv": "## 👉 Ātrās problēmu novēršanas kontrolsaraksts \n\nPirms ziņojuma iesniegšanas, lūdzu, pārliecinieties, vai esat izmēģinājis šīs darbības: \n\n- Izmantojiet ieteicamo pārlūkprogrammu (Chrome) \n- Atsvaidziniet lapu \n- Aizveriet un atkārtoti atveriet pārlūkprogrammu \n- Notīriet pārlūkprogrammas vēsturi/kešatmiņu \n- Pārbaudiet, vai interneta savienojums ir ātrs",
        "nl": "## 👉Checklist voor snelle probleemoplossing \n\nZorg ervoor dat u deze stappen heeft geprobeerd voordat u een rapport indient: \n\n- Gebruik een aanbevolen browser (Chrome) \n- Vernieuw de pagina \n- Sluit en open uw browser opnieuw \n- Wis uw browsergeschiedenis/cache \n- Controleer of uw internetverbinding snel is",
        "pl": "## 👉 Szybka lista kontrolna rozwiązywania problemów\n\nUpewnij się, że wykonałeś te kroki przed wysłaniem zgłoszenia:\n\n- Użyj zalecanej przeglądarki (Chrome)  \n- Odśwież stronę  \n- Zamknij i ponownie otwórz przeglądarkę  \n- Wyczyść historię/pamięć podręczną przeglądarki  \n- Sprawdź, czy Twoje połączenie internetowe jest szybkie",
        "pt": "## 👉 Lista de verificação para solução rápida de problemas \n\nCertifique-se de ter tentado estas etapas antes de enviar um relatório: \n\n- Use um navegador recomendado (Chrome) \n- Atualize a página \n- Feche e reabra seu navegador \n- Limpe o histórico/cache do seu navegador \n- Verifique se sua conexão com a internet é rápida",
        "sk": "## 👉 Rýchly kontrolný zoznam na riešenie problémov \n\nPred odoslaním hlásenia sa uistite, že ste vyskúšali tieto kroky: \n\n- Použite odporúčaný prehliadač (Chrome) \n- Obnovte stránku \n- Zatvorte a znova otvorte prehliadač \n- Vymažte históriu / vyrovnávaciu pamäť prehliadača \n- Skontrolujte, či je vaše internetové pripojenie rýchle",
        "th": "## 👉 รายการตรวจสอบการแก้ไขปัญหาอย่างรวดเร็ว\n\nโปรดตรวจสอบให้แน่ใจว่าคุณได้ลองทำตามขั้นตอนเหล่านี้ก่อนที่จะส่งรายงาน:\n\n- ใช้เบราว์เซอร์ที่แนะนำ (Chrome)  \n- รีเฟรชหน้าเว็บ  \n- ปิดและเปิดเบราว์เซอร์ของคุณอีกครั้ง  \n- ล้างประวัติ/แคชของเบราว์เซอร์  \n- ตรวจสอบว่าการเชื่อมต่ออินเทอร์เน็ตของคุณรวดเร็ว"
    },
